export default {"id":"note-level-16","number":16,"title":"B Accessibility","skillBand":"Textbook","duration":"From the course textbook","summary":"b.1","modules":[{"id":"note-m-1-101-2","code":"1","title":"b.1","blurb":"b.1","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l-b-1","title":"B.1 — High Contrast theme","blocks":[{"type":"step","title":"B.1 — High Contrast theme","blocks":[{"type":"prose","html":"<em>APPENDIX B · Accessibility &amp; teaching tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Turn on Note’s <strong>High Contrast</strong> theme and know it is the AAA-rated theme from 1.0.12."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual §2.4.1: Preferences → <strong>Themes</strong>: <strong>Dark</strong> or <strong>High Contrast</strong>."},{"type":"prose","html":"RN <strong>1.0.12</strong>: “A dedicated <strong>AAA-rated</strong> High Contrast Theme can be selected in Setting.” Later RNs fix High Contrast bugs (automation line borders 1.5.2; device icons 1.4.3; MIDI Editor chrome 1.5). If something vanishes in High Contrast, check version — do not assume the theme is broken forever."},{"type":"prose","html":"This is the official outdoor / low-vision theme. It is not Live’s theme pack. Sister-course Live accessibility is a different app."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Open App Settings (three dots in the library) → <strong>Preferences</strong> → <strong>Themes</strong>.","Switch to <strong>High Contrast</strong>. Open a Set. Confirm pads, mixer, and Help stay readable.","Switch back to Dark if you prefer it for night work. Know both exist.","Recite: High Contrast = AAA theme, 1.0.12, Themes preference."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where is the control? <strong>Answer:</strong> App Settings → Preferences → Themes.","What does RN 1.0.12 call it? <strong>Answer:</strong> A dedicated AAA-rated High Contrast theme.","Are later High Contrast bugfixes a reason to update? <strong>Answer:</strong> Yes. Several RNs mention High Contrast fixes."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §2.4.1 Themes","Note Release Notes 1.0.12, 1.4.3, 1.5, 1.5.2","https://www.ableton.com/en/release-notes/note/"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Do one Capture in High Contrast. If you teach, this is the theme for sunlight demos."},{"type":"prose","html":"<em>Syllabus ID: <code>note-a2-1</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-2-102-2","code":"2","title":"b.2","blurb":"b.2","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l-b-2","title":"B.2 — VoiceOver improvements timeline (release notes)","blocks":[{"type":"step","title":"B.2 — VoiceOver improvements timeline (release notes)","blocks":[{"type":"prose","html":"<em>APPENDIX B · Accessibility &amp; teaching tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Treat VoiceOver support as a <strong>version timeline</strong> from the Note release notes, not as one mythical “complete” mode."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Sourced RN accessibility line-items (not exhaustive of iOS itself):"},{"type":"list","items":["<strong>1.0.6:</strong> more icon names; overlay menus modal; <strong>Direct-Touch</strong> on Pads and Waveform; more Session clip location context.","<strong>1.0.10 / 1.0.12:</strong> more screen-reader work; dials no longer direct-touch; library popups visible to VoiceOver; faders behave as sliders; Capture buffer timeout <strong>removed when VoiceOver is enabled</strong>.","<strong>1.0.15:</strong> announce min/max values; better VO for Export, Keys &amp; Scales, Tap Tempo; library row-by-row; Quantize hint.","<strong>2.0.1:</strong> VoiceOver support for <strong>visual controls</strong> and focused single-parameter access."],"ordered":false},{"type":"prose","html":"{type:'gap'} Ableton does not publish a full VoiceOver user guide for Note in these extracts. Use iOS VoiceOver plus this timeline. If a control is silent, check Help version before filing a bug (FAQ contact form)."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Write your Note version.","Tick which RN blocks you have (1.0.6 / 1.0.12 / 1.0.15 / 2.0.1).","Optional: enable iOS VoiceOver and move through Session → Instrument View. Note anything silent.","Recite: VO is versioned; Capture timeout is off when VO is on (1.0.12)."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What happens to Capture Timeout with VoiceOver (1.0.12)? <strong>Answer:</strong> The buffer timeout is removed.","What did 2.0.1 add for VO? <strong>Answer:</strong> Support for visual controls and single-parameter access.","Is there a full Note VO manual in the pack? <strong>Answer:</strong> No. Timeline + iOS VO. Gap."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.0.6, 1.0.10, 1.0.12, 1.0.15, 2.0.1","Note FAQ (bug reports via account contact form)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"If you teach with VO, freeze auto-update (0.2.15) until you have re-tested after a jump to 2.x."},{"type":"prose","html":"<em>Syllabus ID: <code>note-a2-2</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-3-103-2","code":"3","title":"b.3","blurb":"b.3","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l-b-3","title":"B.3 — Show Touches for tutorials","blocks":[{"type":"step","title":"B.3 — Show Touches for tutorials","blocks":[{"type":"prose","html":"<em>APPENDIX B · Accessibility &amp; teaching tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Enable <strong>Show Touches</strong> so every tap is visible when you teach or record."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"Manual §2.4.5.1: enabling <strong>Show Touches</strong> adds a small <strong>white circle</strong> that follows your gestures. It is meant for performance videos and tutorial content."},{"type":"prose","html":"RN 1.0.12 moved touch visualization to <strong>Preferences</strong> in App Settings (it is not a hidden developer switch)."},{"type":"prose","html":"Pair with the screen-recording KB (B.4). Without Show Touches, a recording of pads is just a grid lighting up. With it, a student can see <em>where</em> you tapped."},{"type":"prose","html":"This is a teaching/accessibility aid, not a music feature. Leave it off if the circle distracts you while playing."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["App Settings → <strong>Preferences</strong> → enable <strong>Show Touches</strong>.","Open a Set. Tap pads and sliders. Confirm the white circle tracks your finger.","Disable it and confirm the circle is gone.","Re-enable if you will record in B.4.","Recite: Show Touches = white circle; lives in Preferences (1.0.12)."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What do you see on screen? <strong>Answer:</strong> A small white circle following gestures.","Where is the toggle? <strong>Answer:</strong> Preferences (Manual; RN 1.0.12 moved it there).","Who is it for? <strong>Answer:</strong> Tutorials and performance videos (Manual)."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Ableton Note Manual §2.4.5.1","Note Release Notes 1.0.12","How to Create a Screen Recording in Note"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Leave Show Touches on until B.4 is done."},{"type":"prose","html":"<em>Syllabus ID: <code>note-a2-3</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-4-104-2","code":"4","title":"b.4","blurb":"b.4","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l-b-4","title":"B.4 — Screen recording workflow","blocks":[{"type":"step","title":"B.4 — Screen recording workflow","blocks":[{"type":"prose","html":"<em>APPENDIX B · Accessibility &amp; teaching tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Record Note from Control Center with in-app access and Show Touches, as the official KB describes."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"How to Create a Screen Recording in Note:"},{"type":"list","items":["Add <strong>Screen Recording</strong> to iOS Control Center (Apple Support: Record the screen on iPhone/iPad).","Enable access <strong>within apps</strong> so you can start recording while Note is open.","Enable <strong>Show Touches</strong> in Note.","Open Control Center from Note and start the recording."],"ordered":true},{"type":"prose","html":"Ableton names two uses: reproducible crash reports for Support, and recording a performance. FAQ: crashes already auto-report; a video is extra evidence with steps."},{"type":"prose","html":"Do not invent a built-in Note “Record Lesson” button. It is iOS screen recording."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Follow Apple’s steps to put Screen Recording in Control Center.","Allow recording inside apps.","Note: Show Touches on (B.3).","From Note, open Control Center, start recording, Capture one clip, stop.","Watch the video. Confirm the white circle and audio (if you enabled mic on the iOS record button — {type:'gap'} Ableton does not document the iOS mic toggle; use Apple’s UI)."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["Where do you start the recording? <strong>Answer:</strong> iOS Control Center, from inside Note.","Why Show Touches? <strong>Answer:</strong> So taps are visible (KB + Manual).","Is this a Note export? <strong>Answer:</strong> No. It is an iOS screen recording."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["How to Create a Screen Recording in Note — https://help.ableton.com/hc/en-us/articles/6159094959004","Ableton Note Manual §2.4.5.1","Note FAQ (crash reports)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"Keep one 30-second clip as a teaching sample. Do not upload it to Cloud."},{"type":"prose","html":"<em>Syllabus ID: <code>note-a2-4</code></em>"}]}],"minutes":8}],"exercises":[]},{"id":"note-m-5-105-2","code":"5","title":"b.5","blurb":"b.5","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"note-l-b-5","title":"B.5 — Direct-touch pads/waveforms for accessibility","blocks":[{"type":"step","title":"B.5 — Direct-touch pads/waveforms for accessibility","blocks":[{"type":"prose","html":"<em>APPENDIX B · Accessibility &amp; teaching tools</em>"}]},{"type":"step","title":"Objective","blocks":[{"type":"prose","html":"Know which Note surfaces are <strong>direct-touch</strong> and that <strong>dials stopped being</strong> direct-touch in 1.0.12."}]},{"type":"step","title":"Instruction","blocks":[{"type":"prose","html":"RN <strong>1.0.6</strong>: “Enabled <strong>Direct-Touch Input</strong> on the <strong>Pads</strong> and <strong>Waveform</strong> views.” That is how VoiceOver users can play pads and grab the waveform without the usual indirect VO gestures."},{"type":"prose","html":"RN <strong>1.0.12</strong>: “<strong>Dials are no longer direct touch controls.</strong>” Also: library popups visible to VO; faders as sliders; Capture timeout removed when VO is on."},{"type":"prose","html":"So: pads and waveforms stay direct-touch (1.0.6). Knobs do not (1.0.12). 2.0.1 adds VO for visual controls / focused parameter mode — a later path for filter displays."},{"type":"prose","html":"{type:'gap'} Extracts do not give a full VO gesture map. Pair this with B.2 and Apple’s VoiceOver help."}]},{"type":"step","title":"Procedure","blocks":[{"type":"list","items":["Write the two RN dates: 1.0.6 pads/waveform direct-touch; 1.0.12 dials <em>not</em> direct-touch.","With VO off, play pads and drag a sample waveform (Manual §9).","Optional: VO on, confirm pads still play via direct-touch.","Recite the split: pads/waveform vs dials."],"ordered":true}]},{"type":"step","title":"Self-check","blocks":[{"type":"list","items":["What became direct-touch in 1.0.6? <strong>Answer:</strong> Pads and Waveform views.","What stopped being direct-touch in 1.0.12? <strong>Answer:</strong> Dials.","What did 2.0.1 add? <strong>Answer:</strong> VoiceOver for visual controls and single-parameter access."],"ordered":true}]},{"type":"step","title":"Sources","blocks":[{"type":"list","items":["Note Release Notes 1.0.6, 1.0.12, 2.0.1","Ableton Note Manual §9 (waveform gestures)"],"ordered":false}]},{"type":"step","title":"Exercise","blocks":[{"type":"prose","html":"If you teach VO users, demo pads first, then a waveform start-point drag, then a dial via VO — three different input modes."},{"type":"prose","html":"<em>Syllabus ID: <code>note-a2-5</code></em>"}]}],"minutes":8}],"exercises":[]}]};
